-- Server-side fixed-window rate limiting for sensitive API operations.
-- Identifiers are keyed HMAC hashes generated by the application; raw phone numbers,
-- user IDs and OTP session IDs are never stored in this table.

create table if not exists public.api_rate_limits (
  bucket_key text not null,
  window_start bigint not null,
  request_count integer not null default 0 check (request_count > 0),
  expires_at timestamptz not null,
  primary key (bucket_key, window_start)
);

create index if not exists api_rate_limits_expires_at_idx
  on public.api_rate_limits (expires_at);

alter table public.api_rate_limits enable row level security;
revoke all on table public.api_rate_limits from public, anon, authenticated, service_role;

create or replace function public.consume_api_rate_limit(
  p_bucket_key text,
  p_limit integer,
  p_window_seconds integer
)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_window_start bigint;
  v_count integer;
begin
  if p_bucket_key is null or length(p_bucket_key) <> 64
     or p_limit is null or p_limit < 1 or p_limit > 1000
     or p_window_seconds is null or p_window_seconds < 1 or p_window_seconds > 86400 then
    raise exception 'Invalid rate-limit parameters';
  end if;

  -- Remove expired entries for this bucket so rate-limit storage stays bounded.
  delete from public.api_rate_limits
  where bucket_key = p_bucket_key and expires_at < clock_timestamp();

  v_window_start := floor(extract(epoch from clock_timestamp()) / p_window_seconds)::bigint;

  insert into public.api_rate_limits (bucket_key, window_start, request_count, expires_at)
  values (
    p_bucket_key,
    v_window_start,
    1,
    to_timestamp((v_window_start + 1) * p_window_seconds)
  )
  on conflict (bucket_key, window_start)
  do update set request_count = public.api_rate_limits.request_count + 1
  where public.api_rate_limits.request_count < p_limit
  returning request_count into v_count;

  return found;
end;
$$;

revoke all on function public.consume_api_rate_limit(text, integer, integer) from public, anon, authenticated;
grant execute on function public.consume_api_rate_limit(text, integer, integer) to service_role;

-- Store provider OTP session metadata server-side. The browser gets only a
-- random opaque token; phone and provider session ID are never trusted from cookies.
create table if not exists public.phone_otp_sessions (
  token_hash text primary key check (length(token_hash) = 64),
  firebase_uid text not null,
  phone text not null check (phone ~ '^\+91[6-9][0-9]{9}$'),
  provider_session_id text not null,
  expires_at timestamptz not null,
  consumed_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists phone_otp_sessions_user_created_idx
  on public.phone_otp_sessions (firebase_uid, created_at desc);

create index if not exists phone_otp_sessions_expires_at_idx
  on public.phone_otp_sessions (expires_at);

alter table public.phone_otp_sessions enable row level security;
revoke all on table public.phone_otp_sessions from public, anon, authenticated;
grant select, insert, update, delete on table public.phone_otp_sessions to service_role;
